1610	/****************************************************************************
1611	 * Name: esp32s3_attach
1612	 *
1613	 * Description:
1614	 *   Attach and prepare interrupts
1615	 *
1616	 * Input Parameters:
1617	 *   dev - An instance of the SDIO device interface
1618	 *
1619	 * Returned Value:
1620	 *   OK on success; A negated errno on failure.
1621	 *
1622	 ****************************************************************************/
1623	
1624	static int esp32s3_attach(struct sdio_dev_s *dev)
1625	{
1626	  int ret;
1627	  uint32_t regval;
1628	  struct esp32s3_dev_s *priv = (struct esp32s3_dev_s *)dev;
1629	
1630	  ret = esp32s3_setup_irq(this_cpu(), ESP32S3_PERIPH_SDIO_HOST,
1631	                          1, ESP32S3_CPUINT_LEVEL);
1632	  DEBUGASSERT(ret >= 0);
1633	
1634	  /* Attach the SDIO interrupt handler */
1635	
1636	  ret = irq_attach(ESP32S3_IRQ_SDIO_HOST, esp32s3_interrupt, dev);
1637	  if (ret == OK)
1638	    {
1639	      /* Disable all interrupts at the SD card controller and clear static
1640	       * interrupt flags
1641	       */
1642	
1643	      esp32s3_putreg(0, ESP32S3_SDMMC_INTMASK);
1644	      esp32s3_putreg(SDMMC_INT_ALL(priv->slot), ESP32S3_SDMMC_RINTSTS);
1645	
1646	      /* Enable Interrupts to happen when the INTMASK is activated */
1647	
1648	      regval  = esp32s3_getreg(ESP32S3_SDMMC_CTRL);
1649	      regval |= SDMMC_CTRL_INTENABLE;
1650	      esp32s3_putreg(regval, ESP32S3_SDMMC_CTRL);
1651	
1652	      /* Enable card detection interrupts */
1653	
1654	      esp32s3_putreg(SDCARD_INT_CDET, ESP32S3_SDMMC_INTMASK);
1655	
1656	      /* Enable SD card interrupts at the NVIC.  They can now be enabled at
1657	       * the SD card controller as needed.
1658	       */
1659	
1660	      up_enable_irq(ESP32S3_IRQ_SDIO_HOST);
1661	    }
1662	
1663	  return ret;
1664	}
