2047	/****************************************************************************
2048	 * Name: esp32s3_recvshortcrc
2049	 *
2050	 * Description:
2051	 *   Receive response to SDIO command.  Only the critical payload is
2052	 *   returned -- 32 bits for 48 bit status.  The driver implementation
2053	 *   verifies the correctness of the remaining, non-returned bits (CRCs, CMD
2054	 *   index, etc.).
2055	 *
2056	 * Input Parameters:
2057	 *   dev  - An instance of the SDIO device interface
2058	 *   Rx   - Buffer in which to receive the response
2059	 *
2060	 * Returned Value:
2061	 *   Number of bytes sent on success; a negated errno on failure.  Here a
2062	 *   failure means only a faiure to obtain the requested response (due to
2063	 *   transport problem -- timeout, CRC, etc.).  The implementation only
2064	 *   assures that the response is returned intacta and does not check errors
2065	 *   within the response itself.
2066	 *
2067	 ****************************************************************************/
2068	
2069	static int esp32s3_recvshortcrc(struct sdio_dev_s *dev, uint32_t cmd,
2070	                                uint32_t *rshort)
2071	{
2072	  uint32_t regval;
2073	  int ret = OK;
2074	
2075	  mcinfo("cmd=%04x\n", cmd);
2076	
2077	  /* R1  Command response (48-bit)
2078	   *     47        0               Start bit
2079	   *     46        0               Transmission bit (0=from card)
2080	   *     45:40     bit5   - bit0   Command index (0-63)
2081	   *     39:8      bit31  - bit0   32-bit card status
2082	   *     7:1       bit6   - bit0   CRC7
2083	   *     0         1               End bit
2084	   *
2085	   * R1b Identical to R1 with the additional busy signaling via the data
2086	   *     line.
2087	   *
2088	   * R6  Published RCA Response (48-bit, SD card only)
2089	   *     47        0               Start bit
2090	   *     46        0               Transmission bit (0=from card)
2091	   *     45:40     bit5   - bit0   Command index (0-63)
2092	   *     39:8      bit31  - bit0   32-bit Argument Field, consisting of:
2093	   *                               [31:16] New published RCA of card
2094	   *                               [15:0]  Card status bits {23,22,19,12:0}
2095	   *     7:1       bit6   - bit0   CRC7
2096	   *     0         1               End bit
2097	   */
2098	
2099	#ifdef CONFIG_DEBUG_FEATURES
2100	  if (!rshort)
2101	    {
2102	      mcerr("ERROR: rshort=NULL\n");
2103	      ret = -EINVAL;
2104	    }
2105	
2106	  /* Check that this is the correct response to this command */
2107	
2108	  else if ((cmd & MMCSD_RESPONSE_MASK) != MMCSD_R1_RESPONSE &&
2109	           (cmd & MMCSD_RESPONSE_MASK) != MMCSD_R1B_RESPONSE &&
2110	           (cmd & MMCSD_RESPONSE_MASK) != MMCSD_R6_RESPONSE)
2111	    {
2112	      mcerr("ERROR: Wrong response CMD=%04x\n", cmd);
2113	      ret = -EINVAL;
2114	    }
2115	  else
2116	#endif
2117	    {
2118	      /* Check if a timeout or CRC error occurred */
2119	
2120	      regval = esp32s3_getreg(ESP32S3_SDMMC_RINTSTS);
2121	      if ((regval & SDMMC_INT_RTO) != 0)
2122	        {
2123	          mcerr("ERROR: Command timeout: %08x\n", regval);
2124	          ret = -ETIMEDOUT;
2125	        }
2126	      else if ((regval & SDMMC_INT_RCRC) != 0)
2127	        {
2128	          mcerr("ERROR: CRC failure: %08x\n", regval);
2129	          ret = -EIO;
2130	        }
2131	    }
2132	
2133	  /* Clear all pending message completion events and return the R1/R6
2134	   * response.
2135	   */
2136	
2137	  esp32s3_putreg(SDCARD_RESPDONE_CLEAR | SDCARD_CMDDONE_CLEAR,
2138	                 ESP32S3_SDMMC_RINTSTS);
2139	  *rshort = esp32s3_getreg(ESP32S3_SDMMC_RESP0);
2140	  mcinfo("CRC=%04x\n", *rshort);
2141	
2142	  return ret;
2143	}
2144	
2145	/****************************************************************************
2146	 * Name: esp32s3_recvlong
2147	 *
2148	 * Description:
2149	 *   Receive response to SDIO command.  Only the critical payload is
2150	 *   returned -- 128 bits for 136 bit status.  The driver implementation
2151	 *   verifies the correctness of the remaining, non-returned bits (CRCs, CMD
2152	 *   index, etc.).
2153	 *
2154	 * Input Parameters:
2155	 *   dev  - An instance of the SDIO device interface
2156	 *   Rx   - Buffer in which to receive the response
2157	 *
2158	 * Returned Value:
2159	 *   Number of bytes sent on success; a negated errno on failure.  Here a

2160	 *   failure means only a faiure to obtain the requested response (due to
2161	 *   transport problem -- timeout, CRC, etc.).  The implementation only
2162	 *   assures that the response is returned intacta and does not check errors
2163	 *   within the response itself.
2164	 *
2165	 ****************************************************************************/
2166	
2167	static int esp32s3_recvlong(struct sdio_dev_s *dev, uint32_t cmd,
2168	                            uint32_t rlong[4])
2169	{
2170	  uint32_t regval;
2171	  int ret = OK;
2172	
2173	  mcinfo("cmd=%04x\n", cmd);
2174	
2175	  /* R2  CID, CSD register (136-bit)
2176	   *     135       0               Start bit
2177	   *     134       0               Transmission bit (0=from card)
2178	   *     133:128   bit5   - bit0   Reserved
2179	   *     127:1     bit127 - bit1   127-bit CID or CSD register
2180	   *                               (including internal CRC)
2181	   *     0         1               End bit
2182	   */
2183	
2184	#ifdef CONFIG_DEBUG_FEATURES
2185	  /* Check that R1 is the correct response to this command */
2186	
2187	  if ((cmd & MMCSD_RESPONSE_MASK) != MMCSD_R2_RESPONSE)
2188	    {
2189	      mcerr("ERROR: Wrong response CMD=%04x\n", cmd);
2190	      ret = -EINVAL;
2191	    }
2192	  else
2193	#endif
2194	    {
2195	      /* Check if a timeout or CRC error occurred */
2196	
2197	      regval = esp32s3_getreg(ESP32S3_SDMMC_RINTSTS);
2198	      if (regval & SDMMC_INT_RTO)
2199	        {
2200	          mcerr("ERROR: Timeout STA: %08x\n", regval);
2201	          ret = -ETIMEDOUT;
2202	        }
2203	      else if (regval & SDMMC_INT_RCRC)
2204	        {
2205	          mcerr("ERROR: CRC fail STA: %08x\n", regval);
2206	          ret = -EIO;
2207	        }
2208	    }
2209	
2210	  /* Return the long response */
2211	
2212	  esp32s3_putreg(SDCARD_RESPDONE_CLEAR | SDCARD_CMDDONE_CLEAR,
2213	                 ESP32S3_SDMMC_RINTSTS);
2214	  if (rlong)
2215	    {
2216	      rlong[0] = esp32s3_getreg(ESP32S3_SDMMC_RESP3);
2217	      rlong[1] = esp32s3_getreg(ESP32S3_SDMMC_RESP2);
2218	      rlong[2] = esp32s3_getreg(ESP32S3_SDMMC_RESP1);
2219	      rlong[3] = esp32s3_getreg(ESP32S3_SDMMC_RESP0);
2220	    }
2221	
2222	  return ret;
2223	}
