2225	/****************************************************************************
2226	 * Name: esp32s3_recvshort
2227	 *
2228	 * Description:
2229	 *   Receive response to SDIO command.  Only the critical payload is
2230	 *   returned -- 32 bits for 48 bit status.  The driver implementation
2231	 *   verifies the correctness of the remaining, non-returned bits (CMD
2232	 *   index, etc., not including CRC).
2233	 *
2234	 * Input Parameters:
2235	 *   dev  - An instance of the SDIO device interface
2236	 *   Rx   - Buffer in which to receive the response
2237	 *
2238	 * Returned Value:
2239	 *   Number of bytes sent on success; a negated errno on failure.  Here a
2240	 *   failure means only a faiure to obtain the requested response (due to
2241	 *   transport problem -- timeout, CRC, etc.).  The implementation only
2242	 *   assures that the response is returned intacta and does not check errors
2243	 *   within the response itself.
2244	 *
2245	 ****************************************************************************/
2246	
2247	static int esp32s3_recvshort(struct sdio_dev_s *dev, uint32_t cmd,
2248	                             uint32_t *rshort)
2249	{
2250	  uint32_t regval;
2251	  int ret = OK;
2252	
2253	  mcinfo("cmd=%04x\n", cmd);
2254	
2255	  /* R3  OCR (48-bit)
2256	   *     47        0               Start bit
2257	   *     46        0               Transmission bit (0=from card)
2258	   *     45:40     bit5   - bit0   Reserved
2259	   *     39:8      bit31  - bit0   32-bit OCR register
2260	   *     7:1       bit6   - bit0   Reserved
2261	   *     0         1               End bit
2262	   */
2263	
2264	  /* Check that this is the correct response to this command */
2265	
2266	#ifdef CONFIG_DEBUG_FEATURES
2267	  if ((cmd & MMCSD_RESPONSE_MASK) != MMCSD_R3_RESPONSE &&
2268	      (cmd & MMCSD_RESPONSE_MASK) != MMCSD_R7_RESPONSE)
2269	    {
2270	      mcerr("ERROR: Wrong response CMD=%04x\n", cmd);
2271	      ret = -EINVAL;
2272	    }
2273	  else
2274	#endif
2275	    {
2276	      /* Check if a timeout occurred (Apparently a CRC error can terminate
2277	       * a good response)
2278	       */
2279	
2280	      regval = esp32s3_getreg(ESP32S3_SDMMC_RINTSTS);
2281	      if (regval & SDMMC_INT_RTO)
2282	        {
2283	          mcerr("ERROR: Timeout STA: %08x\n", regval);
2284	          ret = -ETIMEDOUT;
2285	        }
2286	    }
2287	
2288	  esp32s3_putreg(SDCARD_RESPDONE_CLEAR | SDCARD_CMDDONE_CLEAR,
2289	                 ESP32S3_SDMMC_RINTSTS);
2290	  if (rshort)
2291	    {
2292	      *rshort = esp32s3_getreg(ESP32S3_SDMMC_RESP0);
2293	    }
2294	
2295	  return ret;
2296	}
