2913	/****************************************************************************
2914	 * Name: sdio_initialize
2915	 *
2916	 * Description:
2917	 *   Initialize SDIO for operation.
2918	 *
2919	 * Input Parameters:
2920	 *   slotno - Not used.
2921	 *
2922	 * Returned Value:
2923	 *   A reference to an SDIO interface structure.  NULL is returned on
2924	 *   failures.
2925	 *
2926	 ****************************************************************************/
2927	
2928	struct sdio_dev_s *sdio_initialize(int slotno)
2929	{
2930	  uint32_t regval;
2931	
2932	  struct esp32s3_dev_s *priv = &g_sdiodev;
2933	
2934	  priv->slot = slotno;
2935	  priv->slot_info = &sdmmc_slot_info[slotno];
2936	  priv->sdio_pins = &sdmmc_slot_gpio_sig[slotno];
2937	
2938	  /* enable bus clock */
2939	
2940	  regval = esp32s3_getreg(SYSTEM_PERIP_CLK_EN1_REG);
2941	  regval |= SYSTEM_SDIO_HOST_CLK_EN;
2942	  esp32s3_putreg(regval, SYSTEM_PERIP_CLK_EN1_REG);
2943	
2944	  /* reset registers */
2945	
2946	  regval = esp32s3_getreg(SYSTEM_PERIP_RST_EN1_REG);
2947	  regval |= SYSTEM_SDIO_HOST_RST;
2948	  esp32s3_putreg(regval, SYSTEM_PERIP_RST_EN1_REG);
2949	  regval &= ~SYSTEM_SDIO_HOST_RST;
2950	  esp32s3_putreg(regval, SYSTEM_PERIP_RST_EN1_REG);
2951	
2952	  /* Reset */
2953	
2954	  priv->dev.reset(&priv->dev);
2955	
2956	  /* Pin configuration */
2957	
2958	  configure_pin(CONFIG_ESP32S3_SDMMC_CLK, priv->sdio_pins->clk, OUTPUT);

2959	  configure_pin(CONFIG_ESP32S3_SDMMC_CMD, priv->sdio_pins->cmd,
2960	                INPUT | OUTPUT | PULLUP);
2961	  configure_pin(CONFIG_ESP32S3_SDMMC_D0, priv->sdio_pins->d0,
2962	                INPUT | OUTPUT | PULLUP);
2963	
2964	  esp32s3_gpio_matrix_in(GPIO_MATRIX_CONST_ONE_INPUT,
2965	                         priv->slot_info->card_int, false);
2966	  esp32s3_gpio_matrix_in(GPIO_MATRIX_CONST_ZERO_INPUT,
2967	                         priv->slot_info->card_detect, false);
2968	  esp32s3_gpio_matrix_in(GPIO_MATRIX_CONST_ONE_INPUT,
2969	                         priv->slot_info->write_protect, true);
2970	
2971	  return &priv->dev;
2972	}
